-  if (state.orders) return `${state.orders.length} orders`;
-  return "";
+  switch (state.kind) {
+    case "idle":
+      return "";
+    case "loading":
+      return "Loading orders…";
+    case "retrying":
+      return `Retrying (attempt ${state.attempt} of ${MAX_ATTEMPTS})…`;
+    case "failed":
+      return `Couldn't load orders: ${state.message}`;
+    case "loaded":
+      return state.orders.length === 0 ? "No orders yet" : `${state.orders.length} orders`;
+    default: {
+      const _exhaustive: never = state;
+      return _exhaustive;
+    }
+  }
+}
+
+/** Fetches orders, dispatching events; makes up to MAX_ATTEMPTS attempts in total. */
+export async function loadOrders({
+  fetchOrders,
+  dispatch,
+}: {
+  fetchOrders: () => Promise<Order[]>;
+  dispatch: (event: OrdersEvent) => void;
+}): Promise<void> {
+  dispatch({ type: "fetch" });
+  for (let attempt = 1; ; attempt++) {
+    try {
+      dispatch({ type: "loaded", orders: await fetchOrders() });
+      return;
+    } catch (error) {
+      if (attempt >= MAX_ATTEMPTS) {
+        dispatch({ type: "failed", message: error instanceof Error ? error.message : String(error) });
+        return;
+      }
+      dispatch({ type: "retry", attempt: attempt + 1 });
+    }
+  }
 }
